/*
 * A279353  a(n) = A055938(n+1) XOR A055938(n).
 * https://oeis.org/A279353
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = A055938(n+1) XOR A055938(n); A055938 lists the integers
 *            missing from A005187(k) = 2k - popcount(k), generated by gaps
 * Range:     u8 n <= 126, u16 n <= 8191, u32 n <= 8191, u64 n <= 8191,
 *            u128 n <= 8191, big any n
 * Validated: standard, pass, 121 terms through n = 7359 (2026-11-08)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>
#include "../utils/mem.h"

static seq_t *A055938_miss = NULL;
static size_t A055938_len = 0, A055938_cap = 0;
static idx_t A055938_k = 1;

static void A055938_push(seq_t v)
{
    if (A055938_len == A055938_cap) {
        size_t nc = A055938_cap ? A055938_cap * 2 : 64;
        seq_t *tmp = mem_resize(seq_t, A055938_miss, nc);
        if (!tmp) exit(1);
        A055938_miss = tmp;
        A055938_cap = nc;
    }
    A055938_miss[A055938_len++] = v;
}

static seq_t A055938_a(idx_t n)
{
    while (A055938_len < (size_t)n) {
        idx_t k = A055938_k;
        unsigned pc = 0, t = 0;
        idx_t x = k;
        while (x) { pc += (unsigned)(x & 1); x >>= 1; }
        x = k;
        while (x & 1) { t++; x >>= 1; }
        seq_t f = (seq_t)2 * (seq_t)k - (seq_t)pc;
        for (unsigned i = 1; i <= t; i++)
            A055938_push(f + (seq_t)i);
        A055938_k++;
    }
    return A055938_miss[(size_t)n - 1];
}

seq_t a(idx_t n)
{
    return A055938_a(n + 1) ^ A055938_a(n);
}
